import logging
import sys

from app.core.config import settings


def setup_logging() -> logging.Logger:
    logging.basicConfig(
        level=getattr(logging, settings.log_level.upper(), logging.INFO),
        format="%(asctime)s | %(levelname)s | %(name)s | %(message)s",
        handlers=[logging.StreamHandler(sys.stdout)],
    )
    return logging.getLogger("agentic_graphrag")

class BackendError(Exception):
    """Base application error."""


class ValidationError(BackendError):
    """Raised when request or file validation fails."""


class StorageError(BackendError):
    """Raised when persistence fails."""


class RetrievalError(BackendError):
    """Raised when retrieval or graph lookup fails."""


class IngestionError(BackendError):
    """Raised when document processing fails."""


class AgentExecutionError(BackendError):
    """Raised when the control loop fails."""

from __future__ import annotations

from collections.abc import Iterable


class DocumentRepository:
    """A thin placeholder repository for document metadata and chunk records."""

    def __init__(self):
        self.documents: dict[str, dict] = {}
        self.chunks: dict[str, dict] = {}

    def add_document(self, document: dict) -> dict:
        self.documents[document["id"]] = document
        return document

    def add_chunk(self, chunk: dict) -> dict:
        self.chunks[chunk["id"]] = chunk
        return chunk

    def list_documents(self) -> Iterable[dict]:
        return list(self.documents.values())

    def get_document(self, document_id: str) -> dict | None:
        return self.documents.get(document_id)

    def get_chunk(self, chunk_id: str) -> dict | None:
        return self.chunks.get(chunk_id)

from __future__ import annotations


class VectorRepository:
    """Placeholder vector store adapter. Real implementation should use Qdrant."""

    def __init__(self):
        self.collections: dict[str, list[dict]] = {}

    def upsert(self, collection: str, item: dict) -> dict:
        self.collections.setdefault(collection, [])
        self.collections[collection].append(item)
        return item

    def search(self, collection: str, query_vector: list[float], limit: int = 5) -> list[dict]:
        return self.collections.get(collection, [])[:limit]

from __future__ import annotations


class GraphRepository:
    """Placeholder graph store adapter. Real implementation should use Neo4j."""

    def __init__(self):
        self.nodes: dict[str, dict] = {}
        self.relationships: list[dict] = []

    def upsert_node(self, node: dict) -> dict:
        self.nodes[node["id"]] = node
        return node

    def add_relationship(self, rel: dict) -> dict:
        self.relationships.append(rel)
        return rel

    def get_related_nodes(self, node_id: str, depth: int = 1) -> list[dict]:
        return [node for node in self.nodes.values() if node.get("id") == node_id][:1]

from __future__ import annotations

from abc import ABC, abstractmethod


class BaseLLMProvider(ABC):
    @abstractmethod
    def generate(self, prompt: str, **kwargs) -> str:
        raise NotImplementedError


class NullLLMProvider(BaseLLMProvider):
    """Safe default provider for local scaffold/testing."""

    def generate(self, prompt: str, **kwargs) -> str:
        return "This is a placeholder model response until a real provider is wired in."


class EmbeddingProvider(ABC):
    @abstractmethod
    def embed(self, text: str) -> list[float]:
        raise NotImplementedError


class NullEmbeddingProvider(EmbeddingProvider):
    def embed(self, text: str) -> list[float]:
        return [0.0] * 1536

from __future__ import annotations

from typing import Any

from app.core.config import settings
from app.core.exceptions import IngestionError


class IngestionService:
    """Service responsible for validating documents and preparing them for indexing."""

    def validate_file(self, filename: str, content_type: str | None = None, size_bytes: int | None = None) -> dict[str, Any]:
        extension = filename.lower().rsplit(".", 1)[-1] if "." in filename else ""
        allowed = {item.strip().lower() for item in settings.allowed_file_types.split(",") if item.strip()}
        clean_ext = f".{extension}"

        if clean_ext not in allowed:
            raise IngestionError(f"Unsupported file type: {filename}")

        if size_bytes is None:
            size_bytes = 0

        max_bytes = settings.max_file_size_mb * 1024 * 1024
        if size_bytes > max_bytes:
            raise IngestionError(f"File exceeds maximum size of {settings.max_file_size_mb}MB")

        return {
            "filename": filename,
            "extension": clean_ext,
            "content_type": content_type,
            "size_bytes": size_bytes,
        }

    def extract_text(self, file_bytes: bytes, extension: str) -> str:
        if extension == ".txt":
            return file_bytes.decode("utf-8", errors="replace")
        if extension in {".md", ".html"}:
            return file_bytes.decode("utf-8", errors="replace")
        if extension == ".pdf":
            return "[PDF text extraction not implemented in this scaffold]"
        if extension == ".docx":
            return "[DOCX text extraction not implemented in this scaffold]"
        raise IngestionError(f"No extraction routine implemented for {extension}")

    def chunk_text(self, text: str, chunk_size: int | None = None, overlap: int | None = None) -> list[str]:
        chunk_size = chunk_size or settings.default_chunk_size
        overlap = overlap or settings.default_chunk_overlap
        if overlap >= chunk_size:
            raise IngestionError("Chunk overlap must be smaller than the chunk size.")

        chunks: list[str] = []
        start = 0
        while start < len(text):
            end = min(start + chunk_size, len(text))
            chunk = text[start:end]
            if chunk.strip():
                chunks.append(chunk)
            if end == len(text):
                break
            start += chunk_size - overlap
        return chunks

from __future__ import annotations

from datetime import datetime, timezone


class EvaluationService:
    """Benchmark and evaluation service skeleton for fixed benchmark execution."""

    def __init__(self):
        self.dataset_version = "v1.0.0"

    def build_benchmark(self) -> list[dict]:
        return [
            {
                "id": "q1",
                "category": "relationship",
                "question": "What is the relationship between Entity A and Entity D?",
                "expected_answer": "Entity A relates to Entity D through the known graph path.",
                "required_entities": ["Entity A", "Entity D"],
                "required_relationships": ["Entity A -> Entity B -> Entity D"],
                "gold_sources": ["doc-3", "doc-5"],
            },
            {
                "id": "q2",
                "category": "multi-hop",
                "question": "What evidence supports the link between Entity C and Entity D?",
                "expected_answer": "The support is grounded in the graph path and source chunks.",
                "required_entities": ["Entity C", "Entity D"],
                "required_relationships": ["Entity C -> Entity D"],
                "gold_sources": ["doc-5"],
            },
        ]

    def run_benchmark(self) -> dict:
        run_id = f"eval-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}"
        questions = self.build_benchmark()

        return {
            "run_id": run_id,
            "dataset_version": self.dataset_version,
            "status": "completed",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "questions": questions,
            "summary": {
                "total_questions": len(questions),
                "question_types": sorted({q["category"] for q in questions}),
            },
        }

from __future__ import annotations


class MetricsService:
    """Aggregates benchmark metrics and execution summaries."""

    def aggregate(self) -> dict:
        return {
            "total_runs": 0,
            "latest_run": None,
            "modes": {"rag": {}, "graphrag": {}, "agentic": {}},
            "notes": "Metrics are computed from real execution data once evaluation runs are collected.",
        }

