from __future__ import annotations

from typing import Any

import psycopg


class PostgresDocumentRepository:
    """Postgres-backed document metadata store with in-memory fallback for local development/tests."""

    _default_instance: "PostgresDocumentRepository | None" = None

    def __init__(self, dsn: str | None = None):
        self.dsn = dsn
        self._conn = None
        self.documents: dict[str, dict[str, Any]] = {}
        self.chunks: dict[str, dict[str, Any]] = {}
        self._connect()

    @classmethod
    def get_default(cls) -> "PostgresDocumentRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _connect(self) -> None:
        if not self.dsn:
            self._conn = None
            return
        try:
            self._conn = psycopg.connect(self.dsn)
        except Exception:
            self._conn = None

    def create_document(self, document_id: str, title: str, content: str, file_type: str, source: str, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = {
            "id": document_id,
            "title": title,
            "content": content,
            "file_type": file_type,
            "source": source,
            "metadata": metadata or {},
        }
        self.documents[document_id] = payload
        if self._conn is not None:
            with self._conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS documents (
                        id TEXT PRIMARY KEY,
                        title TEXT,
                        content TEXT,
                        file_type TEXT,
                        source TEXT,
                        metadata JSONB
                    )
                    """
                )
                cur.execute(
                    "INSERT INTO documents (id, title, content, file_type, source, metadata) VALUES (%s, %s, %s, %s, %s, %s) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, file_type = EXCLUDED.file_type, source = EXCLUDED.source, metadata = EXCLUDED.metadata",
                    (document_id, title, content, file_type, source, payload["metadata"]),
                )
            self._conn.commit()
        return payload

    def create_chunk(self, chunk_id: str, document_id: str, content: str, chunk_index: int, page: int | None = None, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = {
            "id": chunk_id,
            "document_id": document_id,
            "content": content,
            "chunk_index": chunk_index,
            "page": page,
            "metadata": metadata or {},
        }
        self.chunks[chunk_id] = payload
        if self._conn is not None:
            with self._conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS chunks (
                        id TEXT PRIMARY KEY,
                        document_id TEXT,
                        content TEXT,
                        chunk_index INTEGER,
                        page INTEGER,
                        metadata JSONB
                    )
                    """
                )
                cur.execute(
                    "INSERT INTO chunks (id, document_id, content, chunk_index, page, metadata) VALUES (%s, %s, %s, %s, %s, %s) ON CONFLICT (id) DO UPDATE SET document_id = EXCLUDED.document_id, content = EXCLUDED.content, chunk_index = EXCLUDED.chunk_index, page = EXCLUDED.page, metadata = EXCLUDED.metadata",
                    (chunk_id, document_id, content, chunk_index, page, payload["metadata"]),
                )
            self._conn.commit()
        return payload

    def get_document(self, document_id: str) -> dict[str, Any] | None:
        return self.documents.get(document_id)

    def get_chunk(self, chunk_id: str) -> dict[str, Any] | None:
        return self.chunks.get(chunk_id)

import re
from typing import Any

from neo4j import GraphDatabase

from app.core.config import settings


class GraphRepository:
    """Neo4j-backed graph repository with provenance-aware edges and canonical entity normalization."""

    _default_instance: "GraphRepository | None" = None

    def __init__(self, uri: str | None = None, user: str | None = None, password: str | None = None):
        self.uri = uri or settings.neo4j_uri
        self.user = user or settings.neo4j_user
        self.password = password or settings.neo4j_password
        self._driver = None
        self._memory_nodes: dict[str, dict[str, Any]] = {}
        self._memory_relationships: list[dict[str, Any]] = []
        self._connect()

    @classmethod
    def get_default(cls) -> "GraphRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _connect(self) -> None:
        try:
            self._driver = GraphDatabase.driver(self.uri, auth=(self.user, self.password))
            with self._driver.session() as session:
                session.run("RETURN 1")
        except Exception:
            self._driver = None

    def normalize_entity_name(self, name: str) -> str:
        normalized = re.sub(r"\s+", " ", name).strip()
        return normalized.lower()

    def upsert_entity(self, entity: dict[str, Any]) -> dict[str, Any]:
        canonical_name = entity.get("canonical_name") or entity.get("name")
        key = self.normalize_entity_name(canonical_name)
        record = {
            "id": entity.get("id") or f"entity:{key}",
            "canonical_name": canonical_name,
            "type": entity.get("type", "UNKNOWN"),
            "description": entity.get("description"),
            "confidence": float(entity.get("confidence", 0.0)),
            "metadata": entity.get("metadata") or {},
            "mentions": entity.get("mentions", [canonical_name]),
        }
        self._memory_nodes[record["id"]] = record
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MERGE (e:Entity {id: $id})
                    SET e.canonical_name = $canonical_name,
                        e.type = $type,
                        e.description = $description,
                        e.confidence = $confidence,
                        e.metadata = $metadata,
                        e.mentions = $mentions
                    """,
                    {
                        "id": record["id"],
                        "canonical_name": record["canonical_name"],
                        "type": record["type"],
                        "description": record.get("description"),
                        "confidence": record["confidence"],
                        "metadata": record["metadata"],
                        "mentions": record["mentions"],
                    },
                )
        return record

    def add_relationship(
        self,
        source_entity_id: str,
        target_entity_id: str,
        relationship_type: str,
        confidence: float = 0.9,
        source_document_id: str | None = None,
        source_chunk_id: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        rel = {
            "source": source_entity_id,
            "target": target_entity_id,
            "type": relationship_type,
            "confidence": confidence,
            "source_document_id": source_document_id,
            "source_chunk_id": source_chunk_id,
            "metadata": metadata or {},
        }
        self._memory_relationships.append(rel)
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MATCH (a:Entity {id: $source_entity_id}), (b:Entity {id: $target_entity_id})
                    MERGE (a)-[r:RELATES {type: $relationship_type}]->(b)
                    SET r.confidence = $confidence,
                        r.source_document_id = $source_document_id,
                        r.source_chunk_id = $source_chunk_id,
                        r.metadata = $metadata
                    """,
                    {
                        "source_entity_id": source_entity_id,
                        "target_entity_id": target_entity_id,
                        "relationship_type": relationship_type,
                        "confidence": confidence,
                        "source_document_id": source_document_id,
                        "source_chunk_id": source_chunk_id,
                        "metadata": metadata or {},
                    },
                )
