from __future__ import annotations

import json
import logging
import re
from typing import Any, Protocol

from pydantic import ValidationError

from app.core.config import settings
from app.schemas.extraction import (
    EntityType,
    ExtractedEntity,
    ExtractedRelationship,
    RelationshipType,
    StructuredExtraction,
)

logger = logging.getLogger(__name__)


class ExtractionProvider(Protocol):
    def generate_json(self, prompt: str, schema: dict[str, Any]) -> str:
        ...


class OpenAIExtractionProvider:
    """OpenAI-compatible structured-output provider, loaded only when configured."""

    def __init__(self, api_key: str, model: str):
        self.api_key = api_key
        self.model = model

    def generate_json(self, prompt: str, schema: dict[str, Any]) -> str:
        import httpx

        response = httpx.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {self.api_key}"},
            json={
                "model": self.model,
                "messages": [{"role": "user", "content": prompt}],
                "response_format": {"type": "json_schema", "json_schema": {"name": "graph_extraction", "strict": True, "schema": schema}},
                "temperature": 0,
            },
            timeout=60,
        )
        response.raise_for_status()
        return response.json()["choices"][0]["message"]["content"]


class StructuredExtractionService:
    """Extract typed graph facts, retry invalid provider output once, then use local fallback."""

    def __init__(self, provider: ExtractionProvider | None = None):
        self.provider = provider

    def _provider_or_none(self) -> ExtractionProvider | None:
        if self.provider is not None:
            return self.provider
        if settings.openai_api_key:
            return OpenAIExtractionProvider(settings.openai_api_key, settings.openai_model)
        return None

    def _prompt(self, document_id: str, chunk_id: str, text: str) -> str:
        return f"""Extract only facts explicitly stated in this document chunk.
Use only the allowed entity and relationship enum values in the JSON schema.
Canonicalize aliases to one name where the text makes the alias clear. Do not infer facts.
Every relationship must include the supplied provenance IDs.
document_id={document_id}
chunk_id={chunk_id}

CHUNK:
{text}
"""

    def extract(self, document_id: str, chunk_id: str, text: str) -> StructuredExtraction:
        provider = self._provider_or_none()
        if provider is not None:
            prompt = self._prompt(document_id, chunk_id, text)
            schema = StructuredExtraction.model_json_schema()
            for attempt in range(2):
                try:
                    raw = provider.generate_json(prompt, schema)
                    parsed = StructuredExtraction.model_validate_json(raw)
                    return self._ensure_provenance(parsed, document_id, chunk_id)
                except (ValidationError, ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
                    logger.warning("Structured graph extraction validation failed (attempt %s/2): %s", attempt + 1, exc)
                except Exception as exc:
                    logger.warning("Structured graph extraction provider failed: %s", exc)
                    break
        return self._heuristic_fallback(document_id, chunk_id, text)

    def _ensure_provenance(self, result: StructuredExtraction, document_id: str, chunk_id: str) -> StructuredExtraction:
        relationships = [rel.model_copy(update={"source_document_id": document_id, "source_chunk_id": chunk_id}) for rel in result.relationships]
        return StructuredExtraction(entities=result.entities, relationships=relationships)

    def _heuristic_fallback(self, document_id: str, chunk_id: str, text: str) -> StructuredExtraction:
        names = re.findall(r"\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*\b", text)
        unique_names = list(dict.fromkeys(name.strip() for name in names if name.strip()))
        entities = [ExtractedEntity(canonical_name=name, type=EntityType.ORGANIZATION, confidence=0.35) for name in unique_names]
        relationships = [
            ExtractedRelationship(
                source=left,
                target=right,
                type=RelationshipType.RELATED_TO,
                confidence=0.25,
                source_document_id=document_id,
                source_chunk_id=chunk_id,
            )
            for left, right in zip(unique_names, unique_names[1:])
        ]
        return StructuredExtraction(entities=entities, relationships=relationships)

from app.schemas.extraction import EntityType, RelationshipType
from app.services.extraction_service import StructuredExtractionService


class ValidProvider:
    def __init__(self):
        self.calls = 0

    def generate_json(self, prompt, schema):
        self.calls += 1
        return '{"entities":[{"canonical_name":"Microsoft","type":"ORGANIZATION","confidence":0.98},{"canonical_name":"Azure","type":"PRODUCT","confidence":0.93}],"relationships":[{"source":"Microsoft","target":"Azure","type":"USES","confidence":0.91,"source_document_id":"wrong","source_chunk_id":"wrong"}]}'


class InvalidThenValidProvider:
    def __init__(self):
        self.calls = 0

    def generate_json(self, prompt, schema):
        self.calls += 1
        if self.calls == 1:
            return '{"entities":[{"canonical_name":"Microsoft","type":"NOT_ALLOWED","confidence":2.0}],"relationships":[]}'
        return '{"entities":[{"canonical_name":"Microsoft","type":"ORGANIZATION","confidence":0.8}],"relationships":[]}'


class AlwaysInvalidProvider:
    def generate_json(self, prompt, schema):
        return '{"entities":[{"canonical_name":"Microsoft","type":"NOT_ALLOWED","confidence":2.0}],"relationships":[]}'


def test_structured_extraction_returns_typed_entities_and_provenance():
    provider = ValidProvider()
    result = StructuredExtractionService(provider).extract("doc-1", "doc-1-chunk-0", "Microsoft uses Azure.")

    assert result.entities[0].type == EntityType.ORGANIZATION
    assert result.entities[1].type == EntityType.PRODUCT
    assert result.relationships[0].type == RelationshipType.USES
    assert result.relationships[0].source_document_id == "doc-1"
    assert result.relationships[0].source_chunk_id == "doc-1-chunk-0"
    assert provider.calls == 1


def test_schema_failure_retries_once_then_accepts_valid_output():
    provider = InvalidThenValidProvider()
    result = StructuredExtractionService(provider).extract("doc-2", "doc-2-chunk-1", "Microsoft is an organization.")

    assert provider.calls == 2
    assert result.entities[0].type == EntityType.ORGANIZATION


def test_schema_failure_falls_back_to_heuristic_extraction():
    result = StructuredExtractionService(AlwaysInvalidProvider()).extract(
        "doc-3", "doc-3-chunk-0", "Microsoft works with Azure."
    )

    assert {entity.canonical_name for entity in result.entities} == {"Microsoft", "Azure"}
    assert result.relationships[0].type == RelationshipType.RELATED_TO
    assert result.relationships[0].confidence < 0.5
    assert result.relationships[0].source_document_id == "doc-3"

