from __future__ import annotations

import json
import re
from typing import Any

from neo4j import GraphDatabase

from app.core.config import settings


class GraphRepository:
    """Neo4j-backed graph repository with provenance-aware edges and canonical entity normalization."""

    _default_instance: "GraphRepository | None" = None

    def __init__(self, uri: str | None = None, user: str | None = None, password: str | None = None, backend: str | None = None):
        self.uri = uri or settings.neo4j_uri
        self.user = user or settings.neo4j_user
        self.password = password or settings.neo4j_password
        self.backend = (backend or settings.graph_backend).lower()
        self._driver = None
        self._memory_nodes: dict[str, dict[str, Any]] = {}
        self._memory_relationships: list[dict[str, Any]] = []
        self._connect()

    @classmethod
    def get_default(cls) -> "GraphRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _connect(self) -> None:
        if self.backend != "neo4j":
            return
        try:
            self._driver = GraphDatabase.driver(self.uri, auth=(self.user, self.password))
            with self._driver.session() as session:
                session.run("RETURN 1")
        except Exception:
            self._driver = None

    @property
    def is_live(self) -> bool:
        return self.backend == "neo4j" and self._driver is not None

    def normalize_entity_name(self, name: str) -> str:
        normalized = re.sub(r"[^\w\s]", " ", name, flags=re.UNICODE)
        normalized = re.sub(r"\s+", " ", normalized).strip().lower()
        normalized = re.sub(r"\s+(inc|incorporated|corp|corporation|ltd|limited|llc|co)$", "", normalized)
        return normalized

    def upsert_entity(self, entity: dict[str, Any]) -> dict[str, Any]:
        canonical_name = entity.get("canonical_name") or entity.get("name")
        key = self.normalize_entity_name(canonical_name)
        record = {
            "id": entity.get("id") or f"entity:{key}",
            "canonical_name": canonical_name,
            "type": entity.get("type", "UNKNOWN"),
            "description": entity.get("description"),
            "confidence": float(entity.get("confidence", 0.0)),
            "metadata": entity.get("metadata") or {},
            "mentions": entity.get("mentions", [canonical_name]),
        }
        self._memory_nodes[record["id"]] = record
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MERGE (e:Entity {id: $id})
                    SET e.canonical_name = $canonical_name,
                        e.type = $type,
                        e.description = $description,
                        e.confidence = $confidence,
                        e.metadata = $metadata,
                        e.mentions = $mentions
                    """,
                    {
                        "id": record["id"],
                        "canonical_name": record["canonical_name"],
                        "type": record["type"],
                        "description": record.get("description"),
                        "confidence": record["confidence"],
                        "metadata": json.dumps(record["metadata"], sort_keys=True),
                        "mentions": record["mentions"],
                    },
                )
        return record

    def add_relationship(
        self,
        source_entity_id: str,
        target_entity_id: str,
        relationship_type: str,
        confidence: float = 0.9,
        source_document_id: str | None = None,
        source_chunk_id: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        rel = {
            "source": source_entity_id,
            "target": target_entity_id,
            "type": relationship_type,
            "confidence": confidence,
            "source_document_id": source_document_id,
            "source_chunk_id": source_chunk_id,
            "metadata": metadata or {},
        }
        existing = next(
            (
                item for item in self._memory_relationships
                if item.get("source") == source_entity_id and item.get("target") == target_entity_id
            ),
            None,
        )
        if existing is None:
            self._memory_relationships.append(rel)
        else:
            existing.update(rel)
            rel = existing
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MATCH (a:Entity {id: $source_entity_id}), (b:Entity {id: $target_entity_id})
                    MERGE (a)-[r:RELATES]->(b)
                    SET r.confidence = $confidence,
                        r.type = $relationship_type,
                        r.source_document_id = $source_document_id,
                        r.source_chunk_id = $source_chunk_id,
                        r.metadata = $metadata
                    WITH a, b, r
                    MATCH (a)-[duplicate:RELATES]->(b)
                    WHERE duplicate <> r
                    DELETE duplicate
                    """,
                    {
                        "source_entity_id": source_entity_id,
                        "target_entity_id": target_entity_id,
                        "relationship_type": relationship_type,
                        "confidence": confidence,
                        "source_document_id": source_document_id,
                        "source_chunk_id": source_chunk_id,
                        "metadata": json.dumps(metadata or {}, sort_keys=True),
                    },
                )
        return rel

    def get_related_nodes(self, node_id: str, depth: int = 1) -> list[dict[str, Any]]:
        return [rel for rel in self._memory_relationships if rel.get("source") == node_id or rel.get("target") == node_id][:depth]

    def find_path(self, start_entity: str, end_entity: str, max_depth: int = 3) -> list[str] | None:
        if start_entity == end_entity:
            return [start_entity]

        if self.is_live:
            bounded_depth = max(1, min(int(max_depth), 20))
            with self._driver.session() as session:
                record = session.run(
                    f"""
                    MATCH p = (start:Entity)-[*1..{bounded_depth}]-(end:Entity)
                    WHERE start.id = $start_id AND end.id = $end_id
                    RETURN [node IN nodes(p) | node.id] AS path
                    ORDER BY length(p)
                    LIMIT 1
                    """,
                    start_id=start_entity,
                    end_id=end_entity,
                ).single()
                return list(record["path"]) if record else None

        adjacency: dict[str, list[str]] = {}
        for rel in self._memory_relationships:
            source = rel.get("source")
            target = rel.get("target")
            if source:
                adjacency.setdefault(source, []).append(target)
            if target:
                adjacency.setdefault(target, []).append(source)

        queue = [(start_entity, [start_entity])]
        seen: set[str] = {start_entity}
        while queue:
            current, path = queue.pop(0)
            if len(path) - 1 >= max_depth:
                continue
            for neighbor in adjacency.get(current, []):
                if neighbor in seen:
                    continue
                if neighbor == end_entity:
                    return path + [neighbor]
                seen.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
        return None

    def get_entity_by_name(self, name: str) -> dict[str, Any] | None:
        normalized = self.normalize_entity_name(name)
        if self.is_live:
            with self._driver.session() as session:
                record = session.run(
                    "MATCH (e:Entity) RETURN e ORDER BY e.id",
                )
                for row in record:
                    entity = dict(row["e"])
                    if self.normalize_entity_name(entity.get("canonical_name", "")) == normalized:
                        return entity
            return None
        for entity in self._memory_nodes.values():
            if self.normalize_entity_name(entity.get("canonical_name", "")) == normalized:
                return entity
        return None

    def clear(self) -> None:
        self._memory_nodes.clear()
        self._memory_relationships.clear()
        if self.is_live:
            with self._driver.session() as session:
                session.run("MATCH (n) DETACH DELETE n")
            return
        if self._driver is not None:
            try:
                self._driver.close()
            except Exception:
                pass
            self._driver = None
        self._connect()

    def list_entities(self) -> list[dict[str, Any]]:
        if self.is_live:
            with self._driver.session() as session:
                return [dict(row["e"]) for row in session.run("MATCH (e:Entity) RETURN e ORDER BY e.id")]
        return list(self._memory_nodes.values())

    def list_relationships(self) -> list[dict[str, Any]]:
        if self.is_live:
            with self._driver.session() as session:
                return [
                    {
                        "source": row["source"],
                        "target": row["target"],
                        "type": row["relationship"]["type"],
                        "confidence": row["relationship"].get("confidence", 0.0),
                        "source_document_id": row["relationship"].get("source_document_id"),
                        "source_chunk_id": row["relationship"].get("source_chunk_id"),
                    }
                    for row in session.run(
                        """
                        MATCH (a:Entity)-[r:RELATES]->(b:Entity)
                        RETURN a.id AS source, b.id AS target, r AS relationship
                        ORDER BY source, target
                        """
                    )
                ]
        return list(self._memory_relationships)

from __future__ import annotations

import time
from typing import Any

import httpx

from app.core.config import settings


class GeminiProvider:
    """Small Gemini REST adapter for text and native structured JSON generation."""

    def __init__(self, api_key: str | None = None, model: str | None = None, retry_delay_seconds: float = 1.0):
        self.api_key = api_key or settings.gemini_api_key
        self.model = model or settings.gemini_model
        self.retry_delay_seconds = retry_delay_seconds

    @property
    def configured(self) -> bool:
        return bool(self.api_key)

    def _generate(self, prompt: str, response_schema: dict[str, Any] | None = None) -> str:
        if not self.api_key:
            raise RuntimeError("Gemini API key is not configured")

        generation_config: dict[str, Any] = {"temperature": 0}
        if response_schema is not None:
            generation_config.update({"responseMimeType": "application/json", "responseSchema": response_schema})

        request = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": generation_config,
        }
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent"
        for attempt in range(2):
            response = httpx.post(url, params={"key": self.api_key}, json=request, timeout=60)
            if response.status_code == 429 and attempt == 0:
                time.sleep(self.retry_delay_seconds)
                continue
            response.raise_for_status()
            return response.json()["candidates"][0]["content"]["parts"][0]["text"]
        raise RuntimeError("Gemini generation failed after retry")

    def generate_text(self, prompt: str) -> str:
        return self._generate(prompt)

    def generate_json(self, prompt: str, response_schema: dict[str, Any]) -> str:
        return self._generate(prompt, response_schema=response_schema)

from __future__ import annotations

import json
import logging
import re
from typing import Any, Protocol

from pydantic import ValidationError

from app.core.config import settings
from app.llm.gemini import GeminiProvider
from app.schemas.extraction import (
    EntityType,
    ExtractedEntity,
    ExtractedRelationship,
    RelationshipType,
    StructuredExtraction,
)

logger = logging.getLogger(__name__)


class ExtractionProvider(Protocol):
    def generate_json(self, prompt: str, schema: dict[str, Any]) -> str:
        ...


class GeminiExtractionProvider(GeminiProvider):
    """Gemini structured JSON provider, loaded only when a Gemini key is configured."""

    def __init__(self, api_key: str, model: str):
        super().__init__(api_key=api_key, model=model)


class StructuredExtractionService:
    """Extract typed graph facts, retry invalid provider output once, then use local fallback."""

    def __init__(self, provider: ExtractionProvider | None = None):
        self.provider = provider

    def _provider_or_none(self) -> ExtractionProvider | None:
        if self.provider is not None:
            return self.provider
        if settings.gemini_api_key:
            return GeminiExtractionProvider(settings.gemini_api_key, settings.gemini_model)
        return None

    def _prompt(self, document_id: str, chunk_id: str, text: str) -> str:
        return f"""Extract only facts explicitly stated in this document chunk.
Use only the allowed entity and relationship enum values in the JSON schema.
Canonicalize aliases to one name where the text makes the alias clear. Do not infer facts.
Every relationship must include the supplied provenance IDs.
document_id={document_id}
chunk_id={chunk_id}

CHUNK:
{text}
"""

    def _provider_schema(self) -> dict[str, Any]:
        return {
            "type": "OBJECT",
            "properties": {
                "entities": {
                    "type": "ARRAY",
                    "items": {
                        "type": "OBJECT",
                        "properties": {
                            "canonical_name": {"type": "STRING"},
                            "type": {"type": "STRING", "enum": [item.value for item in EntityType]},
                            "confidence": {"type": "NUMBER"},
                        },
                        "required": ["canonical_name", "type", "confidence"],
                    },
                },
                "relationships": {
                    "type": "ARRAY",
                    "items": {
                        "type": "OBJECT",
                        "properties": {
                            "source": {"type": "STRING"},
                            "target": {"type": "STRING"},
                            "type": {"type": "STRING", "enum": [item.value for item in RelationshipType]},
                            "confidence": {"type": "NUMBER"},
                            "source_document_id": {"type": "STRING"},
                            "source_chunk_id": {"type": "STRING"},
                        },
                        "required": ["source", "target", "type", "confidence", "source_document_id", "source_chunk_id"],
                    },
                },
            },
            "required": ["entities", "relationships"],
        }

    def extract(self, document_id: str, chunk_id: str, text: str) -> StructuredExtraction:
        provider = self._provider_or_none()
        if provider is not None:
            prompt = self._prompt(document_id, chunk_id, text)
            schema = self._provider_schema()
            for attempt in range(2):
                try:
                    raw = provider.generate_json(prompt, schema)
                    parsed = StructuredExtraction.model_validate_json(raw)
                    return self._ensure_provenance(parsed, document_id, chunk_id)
                except (ValidationError, ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
                    logger.warning("Structured graph extraction validation failed (attempt %s/2): %s", attempt + 1, exc)
                except Exception as exc:
                    logger.warning("Structured graph extraction provider failed: %s", exc)
                    break
        return self._heuristic_fallback(document_id, chunk_id, text)

    def _ensure_provenance(self, result: StructuredExtraction, document_id: str, chunk_id: str) -> StructuredExtraction:
        relationships = [rel.model_copy(update={"source_document_id": document_id, "source_chunk_id": chunk_id}) for rel in result.relationships]
        return StructuredExtraction(entities=result.entities, relationships=relationships)

    def _heuristic_fallback(self, document_id: str, chunk_id: str, text: str) -> StructuredExtraction:
        names = re.findall(r"\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*\b", text)
        unique_names = list(dict.fromkeys(name.strip() for name in names if name.strip()))
        entities = [ExtractedEntity(canonical_name=name, type=EntityType.ORGANIZATION, confidence=0.35) for name in unique_names]
        relationships = [
            ExtractedRelationship(
                source=left,
                target=right,
                type=RelationshipType.RELATED_TO,
                confidence=0.25,
                source_document_id=document_id,
                source_chunk_id=chunk_id,
            )
            for left, right in zip(unique_names, unique_names[1:])
        ]
        return StructuredExtraction(entities=entities, relationships=relationships)

