from __future__ import annotations

import json
import re
from typing import Any

from neo4j import GraphDatabase

from app.core.config import settings


class GraphRepository:
    """Neo4j-backed graph repository with provenance-aware edges and canonical entity normalization."""

    _default_instance: "GraphRepository | None" = None

    def __init__(self, uri: str | None = None, user: str | None = None, password: str | None = None, backend: str | None = None):
        self.uri = uri or settings.neo4j_uri
        self.user = user or settings.neo4j_user
        self.password = password or settings.neo4j_password
        self.backend = (backend or settings.graph_backend).lower()
        self._driver = None
        self._memory_nodes: dict[str, dict[str, Any]] = {}
        self._memory_relationships: list[dict[str, Any]] = []
        self._connect()

    @classmethod
    def get_default(cls) -> "GraphRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _connect(self) -> None:
        if self.backend != "neo4j":
            return
        try:
            self._driver = GraphDatabase.driver(self.uri, auth=(self.user, self.password))
            with self._driver.session() as session:
                session.run("RETURN 1")
        except Exception:
            self._driver = None

    @property
    def is_live(self) -> bool:
        return self.backend == "neo4j" and self._driver is not None

    def normalize_entity_name(self, name: str) -> str:
        normalized = re.sub(r"[^\w\s]", " ", name, flags=re.UNICODE)
        normalized = re.sub(r"\s+", " ", normalized).strip().lower()
        normalized = re.sub(r"\s+(inc|incorporated|corp|corporation|ltd|limited|llc|co)$", "", normalized)
        return normalized

    def upsert_entity(self, entity: dict[str, Any]) -> dict[str, Any]:
        canonical_name = entity.get("canonical_name") or entity.get("name")
        key = self.normalize_entity_name(canonical_name)
        record = {
            "id": entity.get("id") or f"entity:{key}",
            "canonical_name": canonical_name,
            "type": entity.get("type", "UNKNOWN"),
            "description": entity.get("description"),
            "confidence": float(entity.get("confidence", 0.0)),
            "metadata": entity.get("metadata") or {},
            "mentions": entity.get("mentions", [canonical_name]),
        }
        self._memory_nodes[record["id"]] = record
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MERGE (e:Entity {id: $id})
                    SET e.canonical_name = $canonical_name,
                        e.type = $type,
                        e.description = $description,
                        e.confidence = $confidence,
                        e.metadata = $metadata,
                        e.mentions = $mentions
                    """,
                    {
                        "id": record["id"],
                        "canonical_name": record["canonical_name"],
                        "type": record["type"],
                        "description": record.get("description"),
                        "confidence": record["confidence"],
                        "metadata": json.dumps(record["metadata"], sort_keys=True),
                        "mentions": record["mentions"],
                    },
                )
        return record

    def add_relationship(
        self,
        source_entity_id: str,
        target_entity_id: str,
        relationship_type: str,
        confidence: float = 0.9,
        source_document_id: str | None = None,
        source_chunk_id: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        rel = {
            "source": source_entity_id,
            "target": target_entity_id,
            "type": relationship_type,
            "confidence": confidence,
            "source_document_id": source_document_id,
            "source_chunk_id": source_chunk_id,
            "metadata": metadata or {},
        }
        identity_key = f"{source_document_id or ''}:{source_chunk_id or ''}"
        rel["identity_key"] = identity_key
        existing = next(
            (
                item for item in self._memory_relationships
                if item.get("source") == source_entity_id
                and item.get("target") == target_entity_id
                and item.get("identity_key") == identity_key
            ),
            None,
        )
        if existing is None:
            self._memory_relationships.append(rel)
        else:
            existing.update(rel)
            rel = existing
        if self._driver is not None:
            with self._driver.session() as session:
                session.run(
                    """
                    MATCH (a:Entity {id: $source_entity_id}), (b:Entity {id: $target_entity_id})
                    MERGE (a)-[r:RELATES {identity_key: $identity_key}]->(b)
                    SET r.confidence = $confidence,
                        r.type = $relationship_type,
                        r.source_document_id = $source_document_id,
                        r.source_chunk_id = $source_chunk_id,
                        r.metadata = $metadata
                    """,
                    {
                        "source_entity_id": source_entity_id,
                        "target_entity_id": target_entity_id,
                        "relationship_type": relationship_type,
                        "identity_key": identity_key,
                        "confidence": confidence,
                        "source_document_id": source_document_id,
                        "source_chunk_id": source_chunk_id,
                        "metadata": json.dumps(metadata or {}, sort_keys=True),
                    },
                )
        return rel

    def find_relationships(self, entity_a: str, entity_b: str) -> list[dict[str, Any]]:
        first = self.get_entity_by_name(entity_a) or self._entity_by_id(entity_a)
        second = self.get_entity_by_name(entity_b) or self._entity_by_id(entity_b)
        if first is None or second is None:
            return []
        first_id = first["id"]
        second_id = second["id"]
        if self.is_live:
            with self._driver.session() as session:
                return [
                    {
                        "source": row["source"],
                        "target": row["target"],
                        "type": row["relationship"]["type"],
                        "confidence": row["relationship"].get("confidence", 0.0),
                        "source_document_id": row["relationship"].get("source_document_id"),
                        "source_chunk_id": row["relationship"].get("source_chunk_id"),
                        "identity_key": row["relationship"].get("identity_key"),
                    }
                    for row in session.run(
                        """
                        MATCH (a:Entity)-[r:RELATES]-(b:Entity)
                        WHERE (a.id = $first_id AND b.id = $second_id)
                           OR (a.id = $second_id AND b.id = $first_id)
                        RETURN a.id AS source, b.id AS target, r AS relationship
                        ORDER BY relationship.identity_key
                        """,
                        first_id=first_id,
                        second_id=second_id,
                    )
                ]
        return [
            item for item in self._memory_relationships
            if {item.get("source"), item.get("target")} == {first_id, second_id}
        ]

    def _entity_by_id(self, entity_id: str) -> dict[str, Any] | None:
        if self.is_live:
            with self._driver.session() as session:
                record = session.run("MATCH (e:Entity {id: $entity_id}) RETURN e", entity_id=entity_id).single()
                return dict(record["e"]) if record else None
        return self._memory_nodes.get(entity_id)

    def get_related_nodes(self, node_id: str, depth: int = 1) -> list[dict[str, Any]]:
        return [rel for rel in self._memory_relationships if rel.get("source") == node_id or rel.get("target") == node_id][:depth]

    def find_path(self, start_entity: str, end_entity: str, max_depth: int = 3) -> list[str] | None:
        if start_entity == end_entity:
            return [start_entity]

        if self.is_live:
            bounded_depth = max(1, min(int(max_depth), 20))
            with self._driver.session() as session:
                record = session.run(
                    f"""
                    MATCH p = (start:Entity)-[*1..{bounded_depth}]-(end:Entity)
                    WHERE start.id = $start_id AND end.id = $end_id
                    RETURN [node IN nodes(p) | node.id] AS path
                    ORDER BY length(p)
                    LIMIT 1
                    """,
                    start_id=start_entity,
                    end_id=end_entity,
                ).single()
                return list(record["path"]) if record else None

        adjacency: dict[str, list[str]] = {}
        for rel in self._memory_relationships:
            source = rel.get("source")
            target = rel.get("target")
            if source:
                adjacency.setdefault(source, []).append(target)
            if target:
                adjacency.setdefault(target, []).append(source)

        queue = [(start_entity, [start_entity])]
        seen: set[str] = {start_entity}
        while queue:
            current, path = queue.pop(0)
            if len(path) - 1 >= max_depth:
                continue
            for neighbor in adjacency.get(current, []):
                if neighbor in seen:
                    continue
                if neighbor == end_entity:
                    return path + [neighbor]
                seen.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
        return None

    def get_entity_by_name(self, name: str) -> dict[str, Any] | None:
        normalized = self.normalize_entity_name(name)
        if self.is_live:
            with self._driver.session() as session:
                record = session.run(
                    "MATCH (e:Entity) RETURN e ORDER BY e.id",
                )
                for row in record:
                    entity = dict(row["e"])
                    if self.normalize_entity_name(entity.get("canonical_name", "")) == normalized:
                        return entity
            return None
        for entity in self._memory_nodes.values():
            if self.normalize_entity_name(entity.get("canonical_name", "")) == normalized:
                return entity
        return None

    def clear(self) -> None:
        self._memory_nodes.clear()
        self._memory_relationships.clear()
        if self.is_live:
            with self._driver.session() as session:
                session.run("MATCH (n) DETACH DELETE n")
            return
        if self._driver is not None:
            try:
                self._driver.close()
            except Exception:
                pass
            self._driver = None
        self._connect()

    def list_entities(self) -> list[dict[str, Any]]:
        if self.is_live:
            with self._driver.session() as session:
                return [dict(row["e"]) for row in session.run("MATCH (e:Entity) RETURN e ORDER BY e.id")]
        return list(self._memory_nodes.values())

    def list_relationships(self) -> list[dict[str, Any]]:
        if self.is_live:
            with self._driver.session() as session:
                return [
                    {
                        "source": row["source"],
                        "target": row["target"],
                        "type": row["relationship"]["type"],
                        "confidence": row["relationship"].get("confidence", 0.0),
                        "source_document_id": row["relationship"].get("source_document_id"),
                        "source_chunk_id": row["relationship"].get("source_chunk_id"),
                        "identity_key": row["relationship"].get("identity_key"),
                    }
                    for row in session.run(
                        """
                        MATCH (a:Entity)-[r:RELATES]->(b:Entity)
                        RETURN a.id AS source, b.id AS target, r AS relationship
                        ORDER BY source, target
                        """
                    )
                ]
        return list(self._memory_relationships)

from __future__ import annotations

from typing import Any

from app.llm.providers import SentenceTransformerEmbeddingProvider
from app.repositories.graph_repository import GraphRepository
from app.repositories.postgres_repository import PostgresDocumentRepository
from app.repositories.vector_repository import VectorRepository
from app.services.verification_service import VerificationService


class AgentToolRegistry:
    """Standalone tools used by the adaptive agent loop."""

    def __init__(self, verifier: VerificationService | None = None):
        self.graph = GraphRepository.get_default()
        self.vector = VectorRepository.get_default()
        self.documents = PostgresDocumentRepository.get_default()
        self.verifier = verifier or VerificationService()

    def search_documents(self, query: str, top_k: int = 5) -> list[dict[str, Any]]:
        vector = SentenceTransformerEmbeddingProvider().embed(query)
        return self.vector.search("document_chunks", vector, limit=top_k)

    def search_entity(self, name: str) -> dict[str, Any] | None:
        return self.graph.get_entity_by_name(name)

    def traverse_graph(self, entity: str, depth: int = 2, relationship_type: str | None = None) -> list[dict[str, Any]]:
        resolved = self.graph.get_entity_by_name(entity) or self.graph._entity_by_id(entity)
        if resolved is None:
            return []
        relationships = self.graph.list_relationships()
        results = []
        frontier = {resolved["id"]}
        visited = set(frontier)
        for current_depth in range(depth):
            next_frontier: set[str] = set()
            for relationship in relationships:
                if relationship_type and relationship.get("type") != relationship_type:
                    continue
                if relationship.get("source") == resolved["id"] and relationship.get("target") in visited:
                    continue
                if relationship.get("source") in frontier or relationship.get("target") in frontier:
                    results.append(relationship)
                    neighbor = relationship.get("target") if relationship.get("source") in frontier else relationship.get("source")
                    if neighbor and neighbor not in visited:
                        next_frontier.add(neighbor)
            visited.update(next_frontier)
            frontier = next_frontier
            if not frontier:
                break
        return results

    def find_relationship(self, entity_a: str, entity_b: str) -> list[dict[str, Any]]:
        return self.graph.find_relationships(entity_a, entity_b)

    def get_source(self, document_id: str, chunk_id: str) -> dict[str, Any] | None:
        return self.documents.get_chunk(chunk_id)

    def verify_claim(self, claim: str, evidence: str):
        return self.verifier.verify_claim(claim, evidence)

    def rewrite_query(self, original_query: str, missing_information: str) -> str:
        return f"{original_query} Focus on {missing_information}."

    def execute(self, action: str, arguments: dict[str, Any]) -> Any:
        tools = {
            "SEARCH_DOCUMENTS": self.search_documents,
            "SEARCH_ENTITY": self.search_entity,
            "TRAVERSE_GRAPH": self.traverse_graph,
            "FIND_RELATIONSHIP": self.find_relationship,
            "GET_SOURCE": self.get_source,
            "VERIFY_CLAIM": self.verify_claim,
            "REWRITE_QUERY": self.rewrite_query,
        }
        if action not in tools:
            raise ValueError(f"Unsupported agent action: {action}")
        return tools[action](**arguments)

from __future__ import annotations

import json
import time
from typing import Any

from pydantic import ValidationError

from app.core.config import settings
from app.llm.gemini import GeminiProvider
from app.llm.prompts import AGENT_DECISION_PROMPT
from app.schemas.agent import AgentAction, AgentDecision, AgentState, AgentToolCall
from app.schemas.api import AgentStep, Citation, EvidenceStatus, QueryMode, QueryResult, RetrievalStats
from app.services.agent_tools import AgentToolRegistry


class AgenticGraphRagService:
    """Adaptive, bounded agent loop with explicit state and sanitized traces."""

    def __init__(self, provider: GeminiProvider | None = None, tools: AgentToolRegistry | None = None):
        self.provider = provider or GeminiProvider()
        self.tools = tools or AgentToolRegistry()

    def _classify(self, query: str) -> tuple[str, list[str]]:
        lowered = query.lower()
        relationship_terms = ("relationship", "connected", "relate", "between", "path", "link", "how does")
        query_type = "RELATIONSHIP" if any(term in lowered for term in relationship_terms) else "FACTUAL"
        tokens = query.replace("?", "").split()
        stopwords = {"What", "Which", "Who", "How", "Is", "Are", "The", "Between", "And", "Does"}
        entities: list[str] = []
        current: list[str] = []
        for token in tokens:
            clean = token.strip(",.!?:;")
            if clean[:1].isupper() and clean not in stopwords:
                current.append(clean)
            elif current:
                entities.append(" ".join(current))
                current = []
        if current:
            entities.append(" ".join(current))
        return query_type, list(dict.fromkeys(entities))

    def _decision_schema(self) -> dict[str, Any]:
        return {
            "type": "OBJECT",
            "properties": {
                "action": {"type": "STRING", "enum": [item.value for item in AgentAction]},
                "reason": {"type": "STRING"},
                "arguments": {"type": "OBJECT"},
            },
            "required": ["action", "reason", "arguments"],
        }

    def _model_decision(self, state: AgentState) -> AgentDecision | None:
        if not self.provider.configured:
            return None
        try:
            raw = self.provider.generate_json(
                AGENT_DECISION_PROMPT.format(state=state.model_dump_json()),
                self._decision_schema(),
            )
            return AgentDecision.model_validate_json(raw)
        except (ValidationError, ValueError, KeyError, TypeError, json.JSONDecodeError):
            state.steps.append({"event": "invalid_decision_rejected"})
            return None
        except Exception:
            state.steps.append({"event": "decision_provider_failed"})
            return None

    def _fallback_decision(self, state: AgentState) -> AgentDecision:
        called = {call.action for call in state.tool_calls}
        if state.conflicts:
            return AgentDecision(action=AgentAction.FINALIZE, reason="Conflicting claims require an explicit conflict result.")
        if state.query_type == "FACTUAL":
            if AgentAction.SEARCH_DOCUMENTS not in called:
                return AgentDecision(action=AgentAction.SEARCH_DOCUMENTS, reason="A factual query needs document evidence first.", arguments={"query": state.query, "top_k": 5})
            return AgentDecision(action=AgentAction.FINALIZE, reason="Retrieved document evidence is sufficient for this factual query.")
        if AgentAction.SEARCH_DOCUMENTS not in called:
            return AgentDecision(action=AgentAction.SEARCH_DOCUMENTS, reason="Start with broad evidence for a relationship query.", arguments={"query": state.query, "top_k": 5})
        searched = {call.arguments.get("name") for call in state.tool_calls if call.action == AgentAction.SEARCH_ENTITY}
        for entity in state.entities:
            if entity not in searched:
                return AgentDecision(action=AgentAction.SEARCH_ENTITY, reason="Resolve a named graph entity before traversal.", arguments={"name": entity})
        if not state.graph_paths:
            if len(state.entities) >= 2:
                return AgentDecision(action=AgentAction.TRAVERSE_GRAPH, reason="Traverse a bounded graph path between the query entities.", arguments={"entity": state.entities[0], "depth": 3})
            return AgentDecision(action=AgentAction.FINALIZE, reason="The query did not resolve two graph entities.")
        if not state.evidence:
            evidence_ref = state.graph_paths[0].get("evidence", [{}])[0]
            return AgentDecision(action=AgentAction.GET_SOURCE, reason="Fetch source text for the traversed graph claim.", arguments={"document_id": evidence_ref.get("source_document_id"), "chunk_id": evidence_ref.get("source_chunk_id")})
        if not state.verification_results:
            return AgentDecision(action=AgentAction.VERIFY_CLAIM, reason="Verify the graph answer against source evidence.", arguments={"claim": state.query, "evidence": self._evidence_text(state)})
        return AgentDecision(action=AgentAction.FINALIZE, reason="The path has source evidence and a verification result.")

    def _choose_decision(self, state: AgentState) -> AgentDecision:
        return self._model_decision(state) or self._fallback_decision(state)

    def _evidence_text(self, state: AgentState) -> str:
        return "\n\n".join(
            [item.get("content", "") for item in state.evidence if item.get("content")]
            + [item.get("content", "") for item in state.retrieved_chunks if item.get("content")]
        )

    def _detect_conflicts(self, relationships: list[dict[str, Any]]) -> list[dict[str, Any]]:
        types = {item.get("type") for item in relationships if item.get("type")}
        documents = {item.get("source_document_id") for item in relationships if item.get("source_document_id")}
        if len(types) > 1 or len(documents) > 1:
            return [{"claims": relationships, "reason": "Multiple relationship claims were found for the same entity pair."}]
        return []

    def _apply_result(self, state: AgentState, decision: AgentDecision, result: Any) -> tuple[int, str]:
        action = decision.action
        if action == AgentAction.SEARCH_DOCUMENTS:
            state.retrieved_chunks = list(result or [])
            if not state.retrieved_chunks:
                state.missing_information.append("supporting document text")
            return len(state.retrieved_chunks), f"Retrieved {len(state.retrieved_chunks)} document chunks."
        if action == AgentAction.SEARCH_ENTITY:
            if result:
                state.evidence.append({"entity": result})
                return 1, f"Resolved entity {result.get('canonical_name', decision.arguments.get('name'))}."
            state.missing_information.append(f"entity:{decision.arguments.get('name')}")
            return 0, "Entity was not found."
        if action == AgentAction.TRAVERSE_GRAPH:
            relationships = list(result or [])
            if relationships:
                state.graph_paths.append({"entity": decision.arguments.get("entity"), "relationships": relationships, "evidence": relationships})
            state.conflicts.extend(self._detect_conflicts(relationships))
            return len(relationships), f"Found {len(relationships)} graph relationships."
        if action == AgentAction.FIND_RELATIONSHIP:
            relationships = list(result or [])
            state.evidence.extend({"relationship": item} for item in relationships)
            state.conflicts.extend(self._detect_conflicts(relationships))
            return len(relationships), f"Found {len(relationships)} relationship claims."
        if action == AgentAction.GET_SOURCE:
            if result:
                state.evidence.append(result)
                return 1, "Loaded the cited source chunk."
            return 0, "The cited source chunk was unavailable."
        if action == AgentAction.VERIFY_CLAIM:
            verification = result.model_dump(mode="json") if hasattr(result, "model_dump") else result
            state.verification_results.append(verification)
            if verification.get("verdict") == "CONTRADICTS":
                state.conflicts.append({"verification": verification})
            return 1, f"Verification verdict: {verification.get('verdict')}."
        if action == AgentAction.REWRITE_QUERY:
            state.query = str(result)
            return 1, "Rewrote the query using missing-information context."
        return 0, "Finalization selected."

    def _answer_from_state(self, state: AgentState) -> str:
        if state.query_type == "RELATIONSHIP" and state.graph_paths:
            relationships = state.graph_paths[0].get("relationships", [])
            return "Graph evidence: " + "; ".join(f"{item.get('source')} -[{item.get('type')}]-> {item.get('target')}" for item in relationships)
        if state.retrieved_chunks:
            return str(state.retrieved_chunks[0].get("content", ""))
        return "Evidence was found, but it was insufficient to form a grounded answer."

    def _final_result(self, state: AgentState, started: float) -> QueryResult:
        citations: list[Citation] = []
        for item in state.retrieved_chunks:
            citations.append(Citation(document_id=item.get("document_id"), chunk_id=item.get("chunk_id"), snippet=str(item.get("content", ""))[:400], score=item.get("score")))
        for path in state.graph_paths:
            for evidence in path.get("evidence", []):
                if evidence.get("source_document_id"):
                    citations.append(Citation(document_id=evidence.get("source_document_id"), chunk_id=evidence.get("source_chunk_id"), score=evidence.get("confidence", 0.0)))
        unique_citations = {(item.document_id, item.chunk_id): item for item in citations}
        if state.conflicts:
            status = EvidenceStatus.CONFLICTING_EVIDENCE
            answer = "Conflicting evidence was found for the requested claim; the agent did not select one side."
            confidence = 0.0
        elif not state.retrieved_chunks and not state.graph_paths:
            status = EvidenceStatus.INSUFFICIENT_EVIDENCE
            answer = "I could not find enough evidence in the current corpus to answer reliably."
            confidence = 0.0
        else:
            status = EvidenceStatus.VERIFIED
            answer = self._answer_from_state(state)
            confidence = min(1.0, round(0.45 + 0.1 * len(state.verification_results) + 0.1 * bool(state.graph_paths), 3))
        elapsed = round((time.perf_counter() - started) * 1000, 2)
        trace = [AgentStep(step=index + 1, action=item["action"], tool=item["tool"], input_summary=item["input_summary"], result_summary=item["result_summary"], status=item["status"], latency_ms=item["latency_ms"]) for index, item in enumerate(state.steps) if item.get("action")]
        return QueryResult(
            mode=QueryMode.AGENTIC,
            answer=answer,
            citations=list(unique_citations.values()),
            confidence=confidence,
            evidence_status=status,
            retrieval_stats=RetrievalStats(top_k=len(state.retrieved_chunks), nodes_searched=len(state.entities), edges_searched=sum(len(path.get("relationships", [])) for path in state.graph_paths), latency_ms=elapsed),
            graph_paths=state.graph_paths,
            agent_steps=trace,
            reasoning_summary=f"Adaptive loop completed with {len(state.tool_calls)} tool calls and {len(trace)} trace steps.",
            latency_ms=elapsed,
        )

    def answer(self, query: str, max_steps: int | None = None, max_tool_calls: int | None = None) -> QueryResult:
        started = time.perf_counter()
        query_type, entities = self._classify(query)
        state = AgentState(query=query, query_type=query_type, entities=entities, hypotheses=[f"Initial query classified as {query_type}."])
        step_limit = max_steps or settings.max_agent_steps
        tool_limit = max_tool_calls or settings.max_tool_calls
        for _ in range(step_limit):
            decision = self._choose_decision(state)
            if decision.action == AgentAction.FINALIZE:
                break
            if len(state.tool_calls) >= tool_limit:
