    result = AgenticGraphRagService(provider=DisabledProvider(), tools=FakeTools()).answer(
        "What is the relationship between Alpha and Omega?"
    )

    assert result.evidence_status == EvidenceStatus.INSUFFICIENT_EVIDENCE
