from typing import Any

from app.core.config import settings

try:
    from qdrant_client import QdrantClient
    from qdrant_client.http import models
except Exception:  # pragma: no cover - fallback for limited environments
    QdrantClient = None
    models = None


class VectorRepository:
    """Vector storage adapter with a real Qdrant path and an in-memory fallback for local tests."""

    _default_instance: "VectorRepository | None" = None

    def __init__(self, url: str | None = None, api_key: str | None = None):
        self.collections: dict[str, list[dict[str, Any]]] = {}
        self._client = None
        if QdrantClient is not None:
            try:
                self._client = QdrantClient(url=url or settings.qdrant_url, api_key=api_key or settings.qdrant_api_key)
                self._client.get_collections()
            except Exception:
                self._client = None

    @classmethod
    def get_default(cls) -> "VectorRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _ensure_collection(self, collection: str, vector_size: int = 384) -> None:
        if self._client is None:
            self.collections.setdefault(collection, [])
            return
        try:
            self._client.get_collection(collection_name=collection)
        except Exception:
            self._client.create_collection(
                collection_name=collection,
                vectors_config=models.VectorParams(size=vector_size, distance=models.Distance.COSINE),
            )

    def upsert(self, collection: str, item: dict[str, Any]) -> dict[str, Any]:
        self._ensure_collection(collection, vector_size=len(item.get("embedding", [])) or 384)
        if self._client is not None:
            payload = {k: v for k, v in item.items() if k != "embedding"}
            point_id = item.get("id") or payload.get("chunk_id") or len(self.collections.get(collection, []))
            self._client.upsert(
                collection_name=collection,
                points=[
                    {
                        "id": point_id,
                        "vector": item.get("embedding", []),
                        "payload": payload,
                    }
                ],
            )
            return item

        self.collections.setdefault(collection, [])
        self.collections[collection].append(item)
        return item

    def search(self, collection: str, query_vector: list[float], limit: int = 5) -> list[dict[str, Any]]:
        if self._client is not None:
            try:
                hits = self._client.search(
                    collection_name=collection,
                    query_vector=query_vector,
                    limit=limit,
                    with_payload=True,
                )
                return [
                    {
                        "id": hit.id,
                        "score": hit.score,
                        **(hit.payload or {}),
                    }
                    for hit in hits
                ]
            except Exception:
                pass

        items = self.collections.get(collection, [])
        if not items:
            return []
        scored = []
        for item in items:
            embedding = item.get("embedding", [])
            if not embedding:
                continue
            similarity = sum(a * b for a, b in zip(query_vector[: len(embedding)], embedding)) / max(1.0, len(embedding))
            scored.append({**item, "score": similarity})
        return sorted(scored, key=lambda x: x["score"], reverse=True)[:limit]

    @property
    def is_live(self) -> bool:
        return self._client is not None

    def add_chunk_embedding(self, document_id: str, chunk_id: str, content: str, embedding: list[float], metadata: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = {
            "document_id": document_id,
            "chunk_id": chunk_id,
            "content": content,
            "metadata": metadata or {},
            "score": 1.0,
            "embedding": embedding,
        }
        return self.upsert("document_chunks", payload)

