from __future__ import annotations

import hashlib
import math
from abc import ABC, abstractmethod
from typing import Any

import httpx

from app.core.config import settings


class BaseLLMProvider(ABC):
    @abstractmethod
    def generate(self, prompt: str, **kwargs) -> str:
        raise NotImplementedError


class NullLLMProvider(BaseLLMProvider):
    """Safe default provider for local scaffold/testing."""

    def generate(self, prompt: str, **kwargs) -> str:
        return "This is a placeholder model response until a real provider is wired in."


class EmbeddingProvider(ABC):
    @abstractmethod
    def embed(self, text: str) -> list[float]:
        raise NotImplementedError

    @property
    def collection_name(self) -> str:
        return "document_chunks"


class NullEmbeddingProvider(EmbeddingProvider):
    def embed(self, text: str) -> list[float]:
        return [0.0] * 1536


class DeterministicEmbeddingProvider(EmbeddingProvider):
    """Local deterministic fallback that keeps the system usable without external model downloads."""

    def __init__(self, dimension: int = 384):
        self.dimension = dimension

    @property
    def collection_name(self) -> str:
        return "document_chunks_deterministic_384"

    def embed(self, text: str) -> list[float]:
        seed = hashlib.sha256(text.encode("utf-8")).hexdigest()
        values: list[float] = []
        for idx in range(self.dimension):
            token = f"{seed}:{idx}"
            raw = int(hashlib.sha256(token.encode("utf-8")).hexdigest(), 16)
            values.append(math.sin(raw / 1_000_000) if raw else 0.0)
        return values


class GeminiEmbeddingProvider(EmbeddingProvider):
    """Gemini embedContent provider with an explicit 768-dimensional output."""

    def __init__(self, api_key: str | None = None, model_name: str | None = None, dimension: int | None = None):
        self.api_key = api_key or settings.gemini_api_key
        self.model_name = model_name or settings.embedding_model
        self.dimension = dimension or settings.embedding_dimension

    @property
    def collection_name(self) -> str:
        return f"document_chunks_{self.model_name.replace('-', '_')}"

    @property
    def configured(self) -> bool:
        return bool(self.api_key)

    def embed(self, text: str) -> list[float]:
        if not self.api_key:
            raise RuntimeError("Gemini embedding API key is not configured")
        response = httpx.post(
            f"https://generativelanguage.googleapis.com/v1beta/models/{self.model_name}:embedContent",
            params={"key": self.api_key},
            json={
                "content": {"parts": [{"text": text}]},
                "outputDimensionality": self.dimension,
            },
            timeout=60,
        )
        response.raise_for_status()
        values = response.json()["embedding"]["values"]
        if len(values) != self.dimension:
            raise ValueError(f"Gemini returned {len(values)} dimensions, expected {self.dimension}")
        return [float(value) for value in values]


class ResilientEmbeddingProvider(EmbeddingProvider):
    def __init__(self, primary: EmbeddingProvider, fallback: EmbeddingProvider):
        self.primary = primary
        self.fallback = fallback
        self.used_fallback = False

    @property
    def collection_name(self) -> str:
        return self.fallback.collection_name if self.used_fallback else self.primary.collection_name

    def embed(self, text: str) -> list[float]:
        try:
            self.used_fallback = False
            return self.primary.embed(text)
        except Exception:
            self.used_fallback = True
            return self.fallback.embed(text)


def get_embedding_provider() -> EmbeddingProvider:
    fallback = DeterministicEmbeddingProvider()
    if settings.embedding_provider.lower() == "deterministic":
        return fallback
    if settings.gemini_api_key:
        return ResilientEmbeddingProvider(GeminiEmbeddingProvider(), fallback)
    return fallback


try:
    from sentence_transformers import SentenceTransformer

    class SentenceTransformerEmbeddingProvider(EmbeddingProvider):
        """Real embedding provider using a local sentence-transformers model when available."""

        def __init__(self, model_name: str | None = None, dimension: int = 384):
            self.model_name = model_name or settings.embedding_model
            self.dimension = dimension
            self._model = None

        def _get_model(self):
            if self._model is None:
                self._model = SentenceTransformer(self.model_name)
            return self._model

        def embed(self, text: str) -> list[float]:
            model = self._get_model()
            embedding = model.encode(text, convert_to_numpy=True)
            return [float(value) for value in embedding]

except Exception:  # pragma: no cover - fallback when model dependencies are absent
    class SentenceTransformerEmbeddingProvider(DeterministicEmbeddingProvider):
        pass

from __future__ import annotations

from typing import Any

from app.llm.providers import get_embedding_provider
from app.repositories.graph_repository import GraphRepository
from app.repositories.postgres_repository import PostgresDocumentRepository
from app.repositories.vector_repository import VectorRepository
from app.services.verification_service import VerificationService


class AgentToolRegistry:
    """Standalone tools used by the adaptive agent loop."""

    def __init__(self, verifier: VerificationService | None = None):
        self.graph = GraphRepository.get_default()
        self.vector = VectorRepository.get_default()
        self.documents = PostgresDocumentRepository.get_default()
        self.verifier = verifier or VerificationService()

    def search_documents(self, query: str, top_k: int = 5) -> list[dict[str, Any]]:
        embedding_provider = get_embedding_provider()
        vector = embedding_provider.embed(query)
        results = self.vector.search(embedding_provider.collection_name, vector, limit=top_k)
        terms = {term.lower() for term in query.split() if len(term) >= 3}
        if terms:
            for item in results:
                content_terms = set(str(item.get("content", "")).lower().split())
                lexical_overlap = len(terms & content_terms) / len(terms)
                item["score"] = max(float(item.get("score", 0.0)), lexical_overlap)
            results.sort(key=lambda item: float(item.get("score", 0.0)), reverse=True)
        return results[:top_k]

    def search_entity(self, name: str) -> dict[str, Any] | None:
        return self.graph.get_entity_by_name(name)

    def traverse_graph(self, entity: str, depth: int = 2, relationship_type: str | None = None) -> list[dict[str, Any]]:
        resolved = self.graph.get_entity_by_name(entity) or self.graph._entity_by_id(entity)
        if resolved is None:
            return []
        relationships = self.graph.list_relationships()
        results = []
        seen_relationships: set[tuple[str | None, str | None, str | None]] = set()
        frontier = {resolved["id"]}
        visited = set(frontier)
        for current_depth in range(depth):
            next_frontier: set[str] = set()
            for relationship in relationships:
                if relationship_type and relationship.get("type") != relationship_type:
                    continue
                if relationship.get("source") == resolved["id"] and relationship.get("target") in visited:
                    continue
                if relationship.get("source") in frontier or relationship.get("target") in frontier:
                    identity = (
                        relationship.get("source"),
                        relationship.get("target"),
                        relationship.get("identity_key"),
                    )
                    if identity in seen_relationships:
                        continue
                    seen_relationships.add(identity)
                    results.append(relationship)
                    neighbor = relationship.get("target") if relationship.get("source") in frontier else relationship.get("source")
                    if neighbor and neighbor not in visited:
                        next_frontier.add(neighbor)
            visited.update(next_frontier)
            frontier = next_frontier
            if not frontier:
                break
        return results

    def find_relationship(self, entity_a: str, entity_b: str) -> list[dict[str, Any]]:
        return self.graph.find_relationships(entity_a, entity_b)

    def get_source(self, document_id: str, chunk_id: str) -> dict[str, Any] | None:
        return self.documents.get_chunk(chunk_id)

    def verify_claim(self, claim: str, evidence: str):
        return self.verifier.verify_claim(claim, evidence)

    def rewrite_query(self, original_query: str, missing_information: str) -> str:
        return f"{original_query} Focus on {missing_information}."

    def execute(self, action: str, arguments: dict[str, Any]) -> Any:
        tools = {
            "SEARCH_DOCUMENTS": self.search_documents,
            "SEARCH_ENTITY": self.search_entity,
            "TRAVERSE_GRAPH": self.traverse_graph,
            "FIND_RELATIONSHIP": self.find_relationship,
            "GET_SOURCE": self.get_source,
            "VERIFY_CLAIM": self.verify_claim,
            "REWRITE_QUERY": self.rewrite_query,
        }
        if action not in tools:
            raise ValueError(f"Unsupported agent action: {action}")
        return tools[action](**arguments)

from __future__ import annotations

import uuid
from typing import Any

from app.core.config import settings

try:
    from qdrant_client import QdrantClient
    from qdrant_client.http import models
except Exception:  # pragma: no cover - fallback for limited environments
    QdrantClient = None
    models = None


class VectorRepository:
    """Vector storage adapter with a real Qdrant path and an in-memory fallback for local tests."""

    _default_instance: "VectorRepository | None" = None

    def __init__(self, url: str | None = None, api_key: str | None = None):
        self.collections: dict[str, list[dict[str, Any]]] = {}
        self._client = None
        if QdrantClient is not None:
            try:
                self._client = QdrantClient(url=url or settings.qdrant_url, api_key=api_key or settings.qdrant_api_key, timeout=3)
                self._client.get_collections()
            except Exception:
                self._client = None

    @classmethod
    def get_default(cls) -> "VectorRepository":
        if cls._default_instance is None:
            cls._default_instance = cls()
        return cls._default_instance

    def _ensure_collection(self, collection: str, vector_size: int = 384) -> None:
        if self._client is None:
            self.collections.setdefault(collection, [])
            return
        try:
            existing = self._client.get_collection(collection_name=collection)
            existing_size = existing.config.params.vectors.size
            if existing_size != vector_size:
                raise ValueError(
                    f"Qdrant collection '{collection}' has dimension {existing_size}, expected {vector_size}. "
                    "Recreate the collection before ingesting with a different embedding model."
                )
        except Exception:
            if self._client.collection_exists(collection):
                raise
            self._client.create_collection(
                collection_name=collection,
                vectors_config=models.VectorParams(size=vector_size, distance=models.Distance.COSINE),
            )

    def upsert(self, collection: str, item: dict[str, Any]) -> dict[str, Any]:
        self._ensure_collection(collection, vector_size=len(item.get("embedding", [])) or 384)
        if self._client is not None:
            payload = {k: v for k, v in item.items() if k != "embedding"}
            raw_point_id = item.get("id") or payload.get("chunk_id") or str(len(self.collections.get(collection, [])))
            try:
                point_id: int | str = int(raw_point_id)
            except (TypeError, ValueError):
                point_id = str(uuid.uuid5(uuid.NAMESPACE_URL, f"{collection}:{raw_point_id}"))
            self._client.upsert(
                collection_name=collection,
                points=[
                    {
                        "id": point_id,
                        "vector": item.get("embedding", []),
                        "payload": payload,
                    }
                ],
            )
            return item

        self.collections.setdefault(collection, [])
        self.collections[collection].append(item)
        return item

    def search(self, collection: str, query_vector: list[float], limit: int = 5) -> list[dict[str, Any]]:
        if self._client is not None:
            try:
                response = self._client.query_points(
                    collection_name=collection,
                    query=query_vector,
                    limit=limit,
                    with_payload=True,
                )
                return [
                    {
                        "id": hit.id,
                        "score": hit.score,
                        **(hit.payload or {}),
                    }
                    for hit in response.points
                ]
